#!/usr/bin/env python3

def translate_dna(dna_sequence):
    """Translate DNA sequence to amino acid sequence using standard genetic code"""
    codon_table = {
        'TTT': 'F', 'TTC': 'F', 'TTA': 'L', 'TTG': 'L',
        'TCT': 'S', 'TCC': 'S', 'TCA': 'S', 'TCG': 'S',
        'TAT': 'Y', 'TAC': 'Y', 'TAA': '*', 'TAG': '*',
        'TGT': 'C', 'TGC': 'C', 'TGA': '*', 'TGG': 'W',
        'CTT': 'L', 'CTC': 'L', 'CTA': 'L', 'CTG': 'L',
        'CCT': 'P', 'CCC': 'P', 'CCA': 'P', 'CCG': 'P',
        'CAT': 'H', 'CAC': 'H', 'CAA': 'Q', 'CAG': 'Q',
        'CGT': 'R', 'CGC': 'R', 'CGA': 'R', 'CGG': 'R',
        'ATT': 'I', 'ATC': 'I', 'ATA': 'I', 'ATG': 'M',
        'ACT': 'T', 'ACC': 'T', 'ACA': 'T', 'ACG': 'T',
        'AAT': 'N', 'AAC': 'N', 'AAA': 'K', 'AAG': 'K',
        'AGT': 'S', 'AGC': 'S', 'AGA': 'R', 'AGG': 'R',
        'GTT': 'V', 'GTC': 'V', 'GTA': 'V', 'GTG': 'V',
        'GCT': 'A', 'GCC': 'A', 'GCA': 'A', 'GCG': 'A',
        'GAT': 'D', 'GAC': 'D', 'GAA': 'E', 'GAG': 'E',
        'GGT': 'G', 'GGC': 'G', 'GGA': 'G', 'GGG': 'G'
    }
    
    # Clean sequence and ensure it starts with ATG
    dna = dna_sequence.replace('\n', '').replace(' ', '').upper()
    if not dna.startswith('ATG'):
        print(f"Warning: Sequence doesn't start with ATG start codon")
    
    protein = ""
    for i in range(0, len(dna)-2, 3):
        codon = dna[i:i+3]
        if len(codon) == 3:
            aa = codon_table.get(codon, 'X')
            if aa == '*':
                break
            protein += aa
    
    return protein

# Target P53 sequence
target_p53 = ""

# Plasmid sequences
plasmids = {
    'A': "",
    'B': "",
    'C': "",
    'D': ""
}

print("Human P53 Protein Analysis")
print("=" * 50)
print(f"Target P53 sequence length: {len(target_p53)} amino acids")
print()

for plasmid_name, dna_seq in plasmids.items():
    print(f"PLASMID {plasmid_name}:")
    protein_seq = translate_dna(dna_seq)
    print(f"  DNA length: {len(dna_seq)} bp")
    print(f"  Protein length: {len(protein_seq)} amino acids")
    
    # Compare sequences
    if protein_seq == target_p53:
        print(f"  ✓ PERFECT MATCH (100% identity)")
    else:
        # Calculate similarity
        matches = sum(1 for a, b in zip(protein_seq, target_p53) if a == b)
        identity = (matches / len(target_p53)) * 100
        print(f"  ✗ {identity:.1f}% identity ({matches}/{len(target_p53)} matches)")
        
        # Find differences
        differences = []
        for i, (a, b) in enumerate(zip(protein_seq, target_p53)):
            if a != b:
                differences.append(f"pos {i+1}: {b}→{a}")
        if differences:
            print(f"  Differences: {', '.join(differences[:5])}")
            if len(differences) > 5:
                print(f"  ... and {len(differences)-5} more")
    print()

print("RECOMMENDATION:")
perfect_matches = []
for plasmid_name, dna_seq in plasmids.items():
    protein_seq = translate_dna(dna_seq)
    if protein_seq == target_p53:
        perfect_matches.append(plasmid_name)

if perfect_matches:
    print(f"Use plasmid(s): {', '.join(perfect_matches)} - these encode the exact P53 protein")
else:
    print("No plasmid produces the exact target sequence")